// analyzer/typeEvaluator.ts:663
/// Builds the TypeEvaluator. Dropped parameters: wrapWithLogger.
pub fn create_type_evaluator(
    import_lookup: ImportLookup,
    evaluator_options: EvaluatorOptions,
) -> P<TypeEvaluator> {
    let node_info = Rc::new(analyzer::analyzer_node_info::create_analyzer_node_info_accessor(
        evaluator_options.node_info_reader.get(),
        None,
    ));
    let speculative_type_tracker = P::new_eval(RefCell::new(SpeculativeTypeTracker {
        _speculative_context_stack: Vec::new(),
        _speculative_type_cache: FxHashMap::default(),
        _active_dependent_types: Vec::new(),
    }));

    // analyzer/typeEvaluator.ts:5327
    let factory = |names: &[jsrt::Atom], message: fn() -> String| (names.to_vec(), message);
    let type_form_special_form_diagnostic_factories: Vec<(Vec<jsrt::Atom>, fn() -> String)> = vec![
        factory(&[jsrt::atom!("Final")], crate::localization::localize::LocMessage::final_context),
        factory(&[jsrt::atom!("Optional")], crate::localization::localize::LocMessage::optional_extra_args),
        factory(&[jsrt::atom!("Protocol")], crate::localization::localize::LocMessage::protocol_not_allowed),
        factory(&[jsrt::atom!("TypedDict")], crate::localization::localize::LocMessage::typed_dict_not_allowed),
        factory(&[jsrt::atom!("TypeAlias")], crate::localization::localize::LocMessage::type_annotation_variable),
        factory(&[jsrt::atom!("Literal")], crate::localization::localize::LocMessage::literal_not_allowed),
        factory(&[jsrt::atom!("TypeGuard"), jsrt::atom!("TypeIs")], crate::localization::localize::LocMessage::type_guard_arg_count),
        factory(&[jsrt::atom!("Union")], crate::localization::localize::LocMessage::union_type_arg_count),
        factory(&[jsrt::atom!("Annotated")], crate::localization::localize::LocMessage::annotated_type_arg_missing),
        factory(&[jsrt::atom!("ClassVar")], crate::localization::localize::LocMessage::class_var_not_allowed),
        factory(&[jsrt::atom!("Required")], crate::localization::localize::LocMessage::required_arg_count),
        factory(&[jsrt::atom!("NotRequired")], crate::localization::localize::LocMessage::not_required_arg_count),
        factory(&[jsrt::atom!("ReadOnly")], crate::localization::localize::LocMessage::read_only_arg_count),
        factory(&[jsrt::atom!("Unpack")], crate::localization::localize::LocMessage::unpack_arg_count),
        factory(&[jsrt::atom!("Concatenate")], crate::localization::localize::LocMessage::concatenate_context),
    ];

    let evaluator = P::new_eval(TypeEvaluator {
        import_lookup,
        evaluator_options,
        node_info: node_info.clone(),
        symbol_resolution_stack: RefCell::new(Vec::new()),
        speculative_type_tracker,
        suppressed_node_stack: RefCell::new(Vec::new()),
        assign_class_to_self_stack: RefCell::new(Vec::new()),
        function_recursion_map: RefCell::new(JsMap::default()),
        code_flow_analyzer_cache: RefCell::new(JsMap::default()),
        type_cache: Cell::new(P::new_eval(RefCell::new(FxHashMap::default()))),
        type_form_type_cache: Cell::new(P::new_eval(RefCell::new(JsMap::default()))),
        effective_type_cache: RefCell::new(FxHashMap::default()),
        expected_type_cache: RefCell::new(JsMap::default()),
        asymmetric_accessor_assignment_cache: RefCell::new(JsSet::default()),
        deferred_class_completions: RefCell::new(Vec::new()),
        cancellation_token: Cell::new(None),
        print_expression_space_count: Cell::new(0),
        incomplete_gen_count: Cell::new(0),
        return_type_inference_context_stack: RefCell::new(Vec::new()),
        return_type_inference_type_cache: Cell::new(None),
        return_type_inference_type_form_type_cache: Cell::new(None),
        signature_tracker_stack: RefCell::new(Vec::new()),
        prefetched: RefCell::new(None),
        type_form_special_form_diagnostic_factories,
        evaluator_interface: OnceCell::new(),
        code_flow_engine: OnceCell::new(),
    });
    evaluator.evaluator_interface.set(evaluator).unwrap();

    // analyzer/typeEvaluator.ts:30591
    let code_flow_engine =
        analyzer::code_flow_engine::get_code_flow_engine(evaluator, speculative_type_tracker, node_info);
    evaluator.code_flow_engine.set(code_flow_engine).unwrap();

    evaluator
}

